{"command":"Get-ChildItem -Path . -Directory | Where-Object { 
    $_.Name -notin @('node_modules', '.claw', '.sandbox-home', '.sandbox-tmp', 'dist', 'build', '.next', 'coverage', '__pycache__') 
} | ForEach-Object {
    Write-Host "`n📁 $($_.Name)" -ForegroundColor Yellow
    Get-ChildItem -Path $_.FullName -Directory | Where-Object { 
        $_.Name -notin @('node_modules', '.claw', '.sandbox-home', '.sandbox-tmp', 'dist', 'build', '.next', 'coverage', '__pycache__') 
    } | ForEach-Object {
        Write-Host "  📁 $($_.Name)"
        Get-ChildItem -Path $_.FullName -Directory | Where-Object { 
            $_.Name -notin @('node_modules', '.claw', '.sandbox-home', '.sandbox-tmp', 'dist', 'build', '.next', 'coverage', '__pycache__') 
        } | ForEach-Object {
            Write-Host "    📁 $($_.Name)"
        }
    }
}","description":"Listar estrutura do projeto com 2 níveis de profundidade, ignorando diretórios específicos"}
